draw:
var dU = p.Q - p.Wby;
ctx.font = '12px ui-sans-serif, system-ui, sans-serif';
ctx.textAlign = 'center';
ctx.textBaseline = 'middle';

var bx = W * 0.5, by = H * 0.5, bw = W * 0.30, bh = H * 0.40;

// the system box
ctx.strokeStyle = C.ink;
ctx.lineWidth = 2;
ctx.strokeRect(bx - bw / 2, by - bh / 2, bw, bh);
ctx.fillStyle = C.faint;
ctx.fillRect(bx - bw / 2, by - bh / 2, bw, bh);

ctx.fillStyle = C.ink;
ctx.fillText('the gas', bx, by - 16);
ctx.fillText('U changes by', bx, by + 4);
ctx.fillText((dU >= 0 ? '+' : '') + dU.toFixed(0) + ' J', bx, by + 22);

// arrow helper
function arrow(x1, y1, x2, y2, col) {
  ctx.strokeStyle = col;
  ctx.fillStyle = col;
  ctx.lineWidth = 2.5;
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x2, y2);
  ctx.stroke();
  var a = Math.atan2(y2 - y1, x2 - x1);
  ctx.beginPath();
  ctx.moveTo(x2, y2);
  ctx.lineTo(x2 - 9 * Math.cos(a - 0.4), y2 - 9 * Math.sin(a - 0.4));
  ctx.lineTo(x2 - 9 * Math.cos(a + 0.4), y2 - 9 * Math.sin(a + 0.4));
  ctx.closePath();
  ctx.fill();
}

// heat arrow on the left: points in when Q > 0
var lx = bx - bw / 2, ox = W * 0.10;
var pulse = 1 + 0.12 * Math.sin(t * 2.2);
if (p.Q >= 0) { arrow(ox, by, lx - 6, by, C.accent); }
else { arrow(lx - 6, by, ox, by, C.accent); }
ctx.fillStyle = C.accent;
ctx.fillText('Q = ' + p.Q.toFixed(0) + ' J', (ox + lx) / 2, by - 20);
ctx.fillStyle = C.ink;
ctx.fillText(p.Q >= 0 ? 'heat in' : 'heat out', (ox + lx) / 2, by + 22);

// work arrow on the right: points out when W > 0
var rx = bx + bw / 2, oxr = W * 0.90;
if (p.Wby >= 0) { arrow(rx + 6, by, oxr, by, C.figure); }
else { arrow(oxr, by, rx + 6, by, C.figure); }
ctx.fillStyle = C.figure;
ctx.fillText('W = ' + p.Wby.toFixed(0) + ' J', (rx + oxr) / 2, by - 20);
ctx.fillStyle = C.ink;
ctx.fillText(p.Wby >= 0 ? 'work out' : 'work in', (rx + oxr) / 2, by + 22);

// piston cartoon on the right edge of the box, nudged by the work arrow
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
var pistonX = rx - 10 + (p.Wby >= 0 ? 5 : -5) * pulse;
ctx.beginPath();
ctx.moveTo(pistonX, by - bh / 2 + 4);
ctx.lineTo(pistonX, by + bh / 2 - 4);
ctx.stroke();

ctx.fillStyle = C.ink;
ctx.fillText('first law:  change in U  =  Q  -  W', W * 0.5, H * 0.90);

out.note = 'dU = Q - W = ' + p.Q.toFixed(0) + ' - (' + p.Wby.toFixed(0) + ') = ' + dU.toFixed(0) + ' J';

ctx.font = '12px ui-sans-serif, system-ui, sans-serif';
ctx.textAlign = 'center';
ctx.textBaseline = 'middle';

var L = W * 0.16, R = W * 0.92, TOP = H * 0.12, BOT = H * 0.80;
var Vmin = 0, Vmax = 0.05, Pmin = 0, Pmax = 5e5;
function X(v) { return L + (v - Vmin) / (Vmax - Vmin) * (R - L); }
function Y(P) { return BOT - (P - Pmin) / (Pmax - Pmin) * (BOT - TOP); }

var V1 = 0.01, P1 = 4e5, V2 = 0.04, P2 = 1e5;
var mode = Math.round(p.path);

// build the path as a list of points
var pts = [];
if (mode === 1) { pts = [[V1, P1], [V2, P1], [V2, P2]]; }
else if (mode === 3) { pts = [[V1, P1], [V1, P2], [V2, P2]]; }
else { for (var i = 0; i <= 40; i++) { var f = i / 40; pts.push([V1 + f * (V2 - V1), P1 + f * (P2 - P1)]); } }

// shade the area under the path
ctx.fillStyle = C.faint;
ctx.beginPath();
ctx.moveTo(X(pts[0][0]), Y(0));
for (var j = 0; j < pts.length; j++) { ctx.lineTo(X(pts[j][0]), Y(pts[j][1])); }
ctx.lineTo(X(pts[pts.length - 1][0]), Y(0));
ctx.closePath();
ctx.fill();

// axes
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1.5;
ctx.beginPath();
ctx.moveTo(L, TOP - 6); ctx.lineTo(L, Y(0)); ctx.lineTo(R, Y(0));
ctx.stroke();
ctx.fillStyle = C.ink;
ctx.save();
ctx.translate(L - 34, (TOP + BOT) / 2);
ctx.rotate(-Math.PI / 2);
ctx.fillText('pressure P  (Pa)', 0, 0);
ctx.restore();
ctx.fillText('volume V  (m3)', (L + R) / 2, H * 0.93);
ctx.textAlign = 'right';
ctx.fillText('4e5', L - 6, Y(4e5));
ctx.fillText('1e5', L - 6, Y(1e5));
ctx.textAlign = 'center';
ctx.fillText('0.01', X(0.01), Y(0) + 14);
ctx.fillText('0.04', X(0.04), Y(0) + 14);

// the path
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2.5;
ctx.beginPath();
for (var k = 0; k < pts.length; k++) {
  if (k === 0) ctx.moveTo(X(pts[k][0]), Y(pts[k][1])); else ctx.lineTo(X(pts[k][0]), Y(pts[k][1]));
}
ctx.stroke();

// a dot travelling along the path
var ph = (t * 0.35) % 1;
var seg, dot;
if (mode === 2) {
  dot = [V1 + ph * (V2 - V1), P1 + ph * (P2 - P1)];
} else {
  var a = pts[0], b = pts[1], c = pts[2];
  if (ph < 0.5) { var f2 = ph / 0.5; dot = [a[0] + f2 * (b[0] - a[0]), a[1] + f2 * (b[1] - a[1])]; }
  else { var f3 = (ph - 0.5) / 0.5; dot = [b[0] + f3 * (c[0] - b[0]), b[1] + f3 * (c[1] - b[1])]; }
}
ctx.fillStyle = C.figure;
ctx.beginPath();
ctx.arc(X(dot[0]), Y(dot[1]), 5, 0, 6.2832);
ctx.fill();

// endpoints
ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(X(V1), Y(P1), 4, 0, 6.2832); ctx.fill();
ctx.beginPath(); ctx.arc(X(V2), Y(P2), 4, 0, 6.2832); ctx.fill();
ctx.fillText('A', X(V1) - 14, Y(P1) - 10);
ctx.fillText('B', X(V2) + 14, Y(P2) - 10);

// work = area under the path
var Wk = 0;
for (var m = 1; m < pts.length; m++) {
  Wk += 0.5 * (pts[m][1] + pts[m - 1][1]) * (pts[m][0] - pts[m - 1][0]);
}
ctx.fillStyle = C.ink;
ctx.fillText('shaded area = work done by the gas', (L + R) / 2, TOP + 4);

var names = ['expand hot, then cool', 'straight line', 'cool first, then expand'];
out.note = names[mode - 1] + ':  W = ' + Wk.toFixed(0) + ' J  (same A, same B, different W)';

ctx.font = '12px ui-sans-serif, system-ui, sans-serif';
ctx.textAlign = 'center';
ctx.textBaseline = 'middle';

var Rg = 8.31, n = 1, Cv = 1.5 * Rg, gam = 5 / 3;
var V0 = 0.02, T0 = p.T0, P0 = n * Rg * T0 / V0;
var mode = Math.round(p.proc);
var rEnd = (mode === 4) ? 1 : p.ratio;

// animate the volume back and forth along the process
var ph = 0.5 - 0.5 * Math.cos(t * 1.1);
var r = 1 + ph * (rEnd - 1);
var V = V0 * r;

function stateAt(rr) {
  var Vv = V0 * rr, Pp, Tt;
  if (mode === 1) { Pp = P0; Tt = T0 * rr; }
  else if (mode === 2) { Tt = T0; Pp = n * Rg * Tt / Vv; }
  else if (mode === 3) { Pp = P0 * Math.pow(rr, -gam); Tt = T0 * Math.pow(rr, 1 - gam); }
  else { Vv = V0; Pp = P0 * (1 + ph * 0.8); Tt = Pp * V0 / (n * Rg); }
  return [Vv, Pp, Tt];
}
var st = stateAt(r);
var Vc = st[0], Pc = st[1], Tc = st[2];

// work done by the gas from the start up to the current state
var Wk;
if (mode === 1) { Wk = P0 * (Vc - V0); }
else if (mode === 2) { Wk = n * Rg * T0 * Math.log(Vc / V0); }
else if (mode === 3) { Wk = n * Cv * (T0 - Tc); }
else { Wk = 0; }
var dU = n * Cv * (Tc - T0);
var Qh = dU + Wk;

// ---- left panel: the cylinder ----
var cx = W * 0.06, cw = W * 0.34, cy = H * 0.18, chh = H * 0.46;
var maxR = 4;
var fill = cw * (Vc / (V0 * maxR));
ctx.fillStyle = C.faint;
ctx.fillRect(cx, cy, fill, chh);
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1.5;
ctx.strokeRect(cx, cy, cw, chh);
ctx.fillStyle = C.figure;
ctx.fillRect(cx + fill, cy, 7, chh);
ctx.fillStyle = C.ink;
ctx.fillText('gas', cx + Math.max(fill / 2, 16), cy + chh / 2);
ctx.fillText('piston', cx + fill + 26, cy - 12);
ctx.textAlign = 'left';
ctx.fillText('T = ' + Tc.toFixed(0) + ' K', cx, cy + chh + 18);
ctx.fillText('P = ' + (Pc / 1000).toFixed(0) + ' kPa', cx, cy + chh + 36);
ctx.fillText('V = ' + Vc.toFixed(4) + ' m3', cx, cy + chh + 54);
ctx.textAlign = 'center';

// ---- right panel: the P-V curve ----
var L = W * 0.52, R2 = W * 0.95, TOP = H * 0.12, BOT = H * 0.74;
var Vhi = V0 * 4.3, Phi = Math.max(P0 * 4.3, 1);
function X(v) { return L + v / Vhi * (R2 - L); }
function Y(P) { return BOT - P / Phi * (BOT - TOP); }
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1.5;
ctx.beginPath();
ctx.moveTo(L, TOP - 4); ctx.lineTo(L, BOT); ctx.lineTo(R2, BOT);
ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText('V', (L + R2) / 2, BOT + 16);
ctx.save(); ctx.translate(L - 14, (TOP + BOT) / 2); ctx.rotate(-Math.PI / 2); ctx.fillText('P', 0, 0); ctx.restore();

ctx.strokeStyle = C.accent;
ctx.lineWidth = 2.5;
ctx.beginPath();
var steps = 50;
for (var i = 0; i <= steps; i++) {
  var rr = 1 + (i / steps) * (rEnd - 1);
  var s2 = stateAt(rr);
  if (i === 0) ctx.moveTo(X(s2[0]), Y(s2[1])); else ctx.lineTo(X(s2[0]), Y(s2[1]));
}
if (mode === 4) { ctx.moveTo(X(V0), Y(P0)); ctx.lineTo(X(V0), Y(P0 * 1.8)); }
ctx.stroke();
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(X(Vc), Y(Pc), 5, 0, 6.2832); ctx.fill();

var names = ['isobaric: P fixed', 'isothermal: T fixed', 'adiabatic: Q = 0', 'isochoric: V fixed'];
ctx.fillStyle = C.ink;
ctx.fillText(names[mode - 1], (L + R2) / 2, H * 0.92);

out.note = names[mode - 1] + '   W = ' + Wk.toFixed(0) + ' J,  dU = ' + dU.toFixed(0) + ' J,  Q = ' + Qh.toFixed(0) + ' J';
